class Solution:
    def maxSubarrays(self, nums):
        n = len(nums)
        INF = float('inf')
        dp = [(INF, 0)] * (n + 1)
        dp[0] = (0, 0)
        for i in range(1, n + 1):
            cur = ~0
            for j in range(i, 0, -1):
                cur &= nums[j - 1]
                s, p = dp[j - 1]
                cand = (s + cur, p + 1)
                if cand < dp[i]:
                    dp[i] = cand
                if cur == 0:
                    break
        return dp[n][1]

