class Solution {
public:
    int maxSubarrays(vector<int>& nums) {
        int n = nums.size();
        const long long INF = LLONG_MAX;
        vector<pair<long long,int>> dp(n + 1, {INF, 0});
        dp[0] = {0, 0};
        for (int i = 1; i <= n; i++) {
            int cur = INT_MAX;
            for (int j = i; j >= 1; j--) {
                cur &= nums[j - 1];
                auto [s, p] = dp[j - 1];
                pair<long long,int> cand{s + cur, p + 1};
                if (cand < dp[i]) dp[i] = cand;
                if (cur == 0) break;
            }
        }
        return dp[n].second;
    }
};

