class Solution {
    public int maxSubarrays(int[] nums) {
        int n = nums.length;
        long[] best = new long[n + 1];
        int[] parts = new int[n + 1];
        Arrays.fill(best, Long.MAX_VALUE);
        best[0] = 0;
        for (int i = 1; i <= n; i++) {
            int cur = Integer.MAX_VALUE;
            for (int j = i; j >= 1; j--) {
                cur &= nums[j - 1];
                long s = best[j - 1] + cur;
                int p = parts[j - 1] + 1;
                if (s < best[i] || (s == best[i] && p > parts[i])) {
                    best[i] = s;
                    parts[i] = p;
                }
                if (cur == 0) break;
            }
        }
        return parts[n];
    }
}

