var maxSubarrays = function(nums) {
    const n = nums.length;
    const INF = Infinity;
    const best = new Array(n + 1).fill(INF);
    const parts = new Array(n + 1).fill(0);
    best[0] = 0;
    for (let i = 1; i <= n; i++) {
        let cur = ~0;
        for (let j = i; j >= 1; j--) {
            cur &= nums[j - 1];
            const s = best[j - 1] + cur, p = parts[j - 1] + 1;
            if (s < best[i] || (s === best[i] && p > parts[i])) {
                best[i] = s;
                parts[i] = p;
            }
            if (cur === 0) break;
        }
    }
    return parts[n];
};

