class Solution {
public:
    int maxSubarrays(vector<int>& nums) {
        int total = INT_MAX;
        for (int x : nums) total &= x;
        if (total != 0) return 1;
        int count = 0, cur = INT_MAX;
        for (int x : nums) {
            cur &= x;
            if (cur == 0) {
                count++;
                cur = INT_MAX;
            }
        }
        return max(count, 1);
    }
};

